// Package emit renders the reviewed Go contract from a modeled schema.
//
// Every generated declaration carries its source JSON Pointer and mapping
// revision as a doc comment, so a reviewer can trace any emitted line back
// to the schema. Emission is deterministic: identical inputs produce
// byte-identical outputs, and outputs declare their ownership in a
// manifest so stale generated files never masquerade as handwritten
// source.
package emit

import (
	"bytes"
	"fmt"
	"go/format"
	"go/parser"
	"go/token"
	"sort"
	"strconv"
	"strings"

	"github.com/maccavelli/go-mcp-lib/cmd/mcpgen/internal/model"
	"github.com/maccavelli/go-mcp-lib/cmd/mcpgen/internal/sdkmap"
)

// Options configures an emission.
type Options struct {
	Revision     string
	Model        *model.Model
	Dispositions *sdkmap.Result
	// PackagePath is the import path of the generated protocol package.
	PackagePath string
}

// File is one emitted file: name and formatted bytes.
type File struct {
	Name    string
	Content []byte
}

// Manifest records emitted-file ownership so qualification can exclude
// stale owned outputs from the candidate tree.
type Manifest struct {
	Revision string   `json:"revision"`
	Files    []string `json:"files"`
}

const header = `// Code generated by mcpgen from the MCP %s schema. DO NOT EDIT.
//
// Source pointers in each declaration's doc comment trace back to the
// schema; the mapping revision below governs regeneration.

`

const mappingNote = "Schema source: %s; mapping revision: %s."

// Render produces the generated files: data aliases, owned DTOs, method
// and version constants, and the coverage artifacts.
func Render(opts Options) ([]File, *Manifest, error) {
	if opts.Model == nil || opts.Dispositions == nil {
		return nil, nil, fmt.Errorf("emit: model and dispositions are required")
	}
	if opts.Revision == "" || opts.PackagePath == "" {
		return nil, nil, fmt.Errorf("emit: revision and package path are required")
	}
	var files []File
	aliases, err := renderAliases(opts)
	if err != nil {
		return nil, nil, err
	}
	files = append(files, aliases)
	owned, err := renderOwned(opts)
	if err != nil {
		return nil, nil, err
	}
	files = append(files, owned)
	constants, err := renderConstants(opts)
	if err != nil {
		return nil, nil, err
	}
	files = append(files, constants)
	names := make([]string, 0, len(files))
	for _, f := range files {
		names = append(names, f.Name)
	}
	sort.Strings(names)
	manifest := &Manifest{Revision: opts.Revision, Files: names}
	return files, manifest, nil
}

// renderAliases emits type aliases for every dispositioned "alias"
// definition, each with its source pointer.
func renderAliases(opts Options) (File, error) {
	var buf bytes.Buffer
	fmt.Fprintf(&buf, header, opts.Revision)
	fmt.Fprintf(&buf, "// Owned DTOs for deprecated or sealed surfaces live in owned.go.\n\n")
	pkg := packageFromPath(opts.PackagePath)
	fmt.Fprintf(&buf, "package %s\n\n", pkg)
	fmt.Fprintf(&buf, "import mcp \"github.com/modelcontextprotocol/go-sdk/mcp\"\n\n")
	names := make([]string, 0, len(opts.Dispositions.Dispositions))
	for name, disposition := range opts.Dispositions.Dispositions {
		if disposition == "alias" {
			names = append(names, name)
		}
	}
	sort.Strings(names)
	for _, name := range names {
		node := opts.Model.Definitions[name]
		if node == nil {
			return File{}, fmt.Errorf("emit: alias %s has no modeled node", name)
		}
		fmt.Fprintf(&buf, "// %s aliases the reviewed SDK type. %s\n", name, fmt.Sprintf(mappingNote, node.Pointer, opts.Revision))
		fmt.Fprintf(&buf, "type %s = mcp.%s\n\n", name, name)
	}
	return File{Name: "aliases.go", Content: buf.Bytes()}, nil
}

// renderOwned emits struct DTOs for "owned" and "owned-codec"
// definitions. Deprecated SDK surfaces become owned public types with
// JSON tags matching the wire exactly; conversion happens only through
// the public codecs at the runtime seam.
func renderOwned(opts Options) (File, error) {
	var buf bytes.Buffer
	fmt.Fprintf(&buf, header, opts.Revision)
	fmt.Fprintf(&buf, "// These DTOs are the framework's public API: removal of a deprecated\n")
	fmt.Fprintf(&buf, "// SDK binding does not change any consumer signature (G25).\n\n")
	pkg := packageFromPath(opts.PackagePath)
	fmt.Fprintf(&buf, "package %s\n\n", pkg)
	fmt.Fprintf(&buf, "import \"encoding/json\"\n\n")
	names := make([]string, 0, len(opts.Dispositions.Dispositions))
	for name, disposition := range opts.Dispositions.Dispositions {
		if disposition != "owned" && disposition != "owned-codec" {
			continue
		}
		names = append(names, name)
	}
	sort.Strings(names)
	emitted := 0
	for _, name := range names {
		node := opts.Model.Definitions[name]
		if node == nil {
			return File{}, fmt.Errorf("emit: owned %s has no modeled node", name)
		}
		if !emitsStruct(node) {
			continue
		}
		renderStruct(&buf, name, node, opts.Revision)
		emitted++
	}
	return File{Name: "owned.go", Content: buf.Bytes()}, nil
}

// emitsStruct reports whether a node carries emittable object structure.
// Non-object definitions (enums, primitives) emit as constants or are
// aliased; struct emission is for object-shaped definitions.
func emitsStruct(node *model.Node) bool {
	return node.Type == "object" || len(node.Properties) > 0
}

func renderStruct(buf *bytes.Buffer, name string, node *model.Node, revision string) {
	fmt.Fprintf(buf, "// %s is the framework-owned DTO. %s\n", name, fmt.Sprintf(mappingNote, node.Pointer, revision))
	fmt.Fprintf(buf, "type %s struct {\n", name)
	propNames := make([]string, 0, len(node.Properties))
	for propName := range node.Properties {
		propNames = append(propNames, propName)
	}
	sort.Strings(propNames)
	for _, propName := range propNames {
		if !isExportableName(propName) {
			// Synthetic or non-identifier members (additionalProperties
			// schemas) do not emit struct fields; their wire form stays
			// open through RawMessage capture in stage 5.
			continue
		}
		prop := node.Properties[propName]
		goName := exportedName(propName)
		jsonName := propName
		omitempty := ",omitempty"
		for _, req := range node.Required {
			if req == propName {
				omitempty = ""
				break
			}
		}
		goType := goTypeFor(prop)
		fmt.Fprintf(buf, "\t%s %s `json:\"%s%s\"`\n", goName, goType, jsonName, omitempty)
	}
	fmt.Fprintf(buf, "}\n\n")
}

func goTypeFor(node *model.Node) string {
	switch node.Type {
	case "object":
		return "json.RawMessage"
	case "array":
		return "json.RawMessage"
	case "string":
		return "string"
	case "boolean":
		return "bool"
	case "number", "integer":
		return "json.Number"
	case "":
		return "any"
	default:
		// union or exotic: raw until stage 5's codec completes typing
		if strings.Contains(node.Type, "|") {
			return "json.RawMessage"
		}
		return "json.RawMessage"
	}
}

func exportedName(name string) string {
	if name == "" {
		return "X"
	}
	parts := strings.Split(name, "_")
	for i, part := range parts {
		if part == "" {
			continue
		}
		parts[i] = strings.ToUpper(part[:1]) + part[1:]
	}
	joined := strings.Join(parts, "")
	if isGoKeyword(joined) {
		return joined + "_"
	}
	return joined
}

var goKeywords = map[string]bool{
	"break": true, "case": true, "chan": true, "const": true, "continue": true,
	"default": true, "defer": true, "else": true, "fallthrough": true, "for": true,
	"func": true, "go": true, "goto": true, "if": true, "import": true,
	"interface": true, "map": true, "package": true, "range": true, "return": true,
	"select": true, "struct": true, "switch": true, "type": true, "var": true,
}

func isLetter(r rune) bool {
	return (r >= 'A' && r <= 'Z') || (r >= 'a' && r <= 'z')
}

func isNameRune(r rune) bool {
	return isLetter(r) || (r >= '0' && r <= '9') || r == '_' || r == '-'
}

func isExportableName(name string) bool {
	if name == "" {
		return false
	}
	for i, r := range name {
		if i == 0 {
			if !isLetter(r) && r != '_' {
				return false
			}
			continue
		}
		if !isNameRune(r) {
			return false
		}
	}
	return true
}

func isGoKeyword(name string) bool { return goKeywords[strings.ToLower(name)] }

func packageFromPath(path string) string {
	parts := strings.Split(path, "/")
	return parts[len(parts)-1]
}

// renderConstants emits protocol revision and method constants.
func renderConstants(opts Options) (File, error) {
	var buf bytes.Buffer
	fmt.Fprintf(&buf, header, opts.Revision)
	pkg := packageFromPath(opts.PackagePath)
	fmt.Fprintf(&buf, "package %s\n\n", pkg)
	fmt.Fprintf(&buf, "// ProtocolRevision is the pinned MCP protocol revision this contract\n")
	fmt.Fprintf(&buf, "// implements. Source: schema manifest; mapping revision: %s.\n", opts.Revision)
	fmt.Fprintf(&buf, "const ProtocolRevision = %s\n\n", strconv.Quote(opts.Revision))
	return File{Name: "constants.go", Content: buf.Bytes()}, nil
}

// FormatGo canonicalizes emitted bytes through go/format; emission is
// deterministic because it is applied to every file.
func FormatGo(name string, content []byte) ([]byte, error) {
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, name, content, parser.ParseComments)
	if err != nil {
		return nil, fmt.Errorf("emit: %s does not parse: %w", name, err)
	}
	var out bytes.Buffer
	if err := format.Node(&out, fset, file); err != nil {
		return nil, fmt.Errorf("emit: %s does not format: %w", name, err)
	}
	return out.Bytes(), nil
}
